#include <bits/stdc++.h>
using namespace std;

long long recursive(long long val, long long depth) {
    long long div = val / b[depth];
    val %= b[depth];
    if (val == 0)
        return div * depth;
    else
        return div * depth + min(recursive(val, depth - 1), depth + recursive(b[depth] - val, depth - 1));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, b[20];
    for (int i = 1; i <= 17; ++i)
        b[i] = b[i - 1] * 10 + 1;
    cin >> n;
    long long count_digits = 0, temp_n = n;
    while (temp_n != 0) {
        temp_n /= 10;
        ++count_digits;
    }
    cout << recursive(n, count_digits + 2) << "\n";
    return 0;
}
